from pathlib import Path
import json,csv
P=Path(__file__).resolve().parent;cs=json.loads((P/'catalog.json').read_text())['characters']
style='''<style>*{box-sizing:border-box}body{margin:0;background:#071622;color:#f2f4ed;font:14px Arial;padding:28px}h1{font-size:28px;letter-spacing:-.7px;margin:8px 0}p{font-size:12px;color:#b4c7cc;line-height:1.7}.ref{display:grid;grid-template-columns:1fr 1.2fr;gap:30px;border:1px solid #47616d;border-radius:14px;padding:20px;margin:22px 0}.ref img{width:100%;height:240px;object-fit:contain}.ref h2{font-size:21px;margin:18px 0 12px}.grid{display:grid;grid-template-columns:repeat(8,1fr);gap:13px}.card{padding:10px;background:#142b3b;border:1px solid #42606d;border-radius:13px;text-align:center}.card img{width:100%;aspect-ratio:1;display:block}.card b{font-size:12px;display:block;margin-top:8px}.card small{font-size:9px;color:#acc3cc;display:block;margin-top:5px}.tiny{display:flex;align-items:center;justify-content:center;gap:6px;margin-top:9px}.tiny img{height:auto;aspect-ratio:1}.tiny .s24{width:24px}.tiny .s32{width:32px}.tiny .s48{width:48px}@media(max-width:800px){.grid{grid-template-columns:repeat(4,1fr)}.ref{grid-template-columns:1fr}.tiny .s48{display:none}}</style>'''
s='<!doctype html><html lang="en"><meta charset="utf-8"><link rel="icon" href="data:,"><title>Playgrid · 32 original avatar candidates</title>'+style+'<p>ISSUE #58 / ORIGINAL LAYERED SVG CHARACTERS / DESIGN REVIEW · NOT IMPLEMENTED</p><h1>One character family. Thirty-two new faces.</h1><div class="ref"><img src="../../../node-server/public/assets/hero-mascots.png" alt="Exact unchanged canonical home illustration"><div><h2>The home illustration is the reference.</h2><p>Oversized chibi heads, dark expressive ink, layered hair/fur/metal, glossy eyes, navy clothing and lime/violet rim light. The original artwork and all 24 classic choices remain unchanged.</p><p>These new vectors translate that family into editable layers. Their finish is cleaner and less painterly than the raster reference; that remaining difference requires owner style review, rather than a claim of identical painted texture.</p></div></div><div class="grid">'
for c in cs:s+=f'<article class="card"><img src="{c["asset"]}" alt="{c["name"]}, original {c["silhouette"]}"><b>{c["name"]}</b><small>{c["family"]} / {c["silhouette"]}</small><div class="tiny"><img class="s24" src="{c["asset"]}" alt="24 pixel preview"><img class="s32" src="{c["asset"]}" alt="32 pixel preview"><img class="s48" src="{c["asset"]}" alt="48 pixel preview"></div></article>'
s+='</div></html>';(P/'character-review.html').write_text(s)
with (P/'COMPATIBILITY.csv').open('w',newline='') as f:
 w=csv.writer(f,lineterminator="\n");w.writerow(['id','name','family','silhouette','hat','glasses','accessory','expressions','eye_styles'])
 for c in cs:w.writerow([c['id'],c['name'],c['family'],c['silhouette'],','.join(c['compatibility']['hat']),','.join(c['compatibility']['glasses']),','.join(c['compatibility']['accessory']),','.join(c['compatibility']['expression']),','.join(c['compatibility']['eyes'])])
print('Character style review and exact compatibility matrix generated.')
